from __future__ import annotations

from typing import Iterator
from unittest.mock import MagicMock

import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from sqlalchemy.pool import StaticPool

from app.core.config import Settings, get_settings
from app.core.database import Base, get_db
from app.libs.auth.deps import get_current_admin_user
from app.libs.identity.deps import get_identity_service
from app.libs.staff.router import _get_service
from app.libs.staff.router import router as staff_router
from app.models.users import AccountStatus, AdminProfile, AdminRole
from tests.conftest import make_admin_stub


class _StubStaffUser:
    """Minimal attribute-bearing stand-in for a User row, returned by the stubbed
    StaffService -- avoids coupling this router test to the exact StaffOut
    construction, which is unimplemented (elided) in the doc's contract."""

    def __init__(
        self, firebase_uid: str, role: str, status: AccountStatus = AccountStatus.ACTIVE
    ) -> None:
        self.firebase_uid = firebase_uid
        self.role = role
        self.status = status


def _make_scratch_app() -> FastAPI:
    app = FastAPI()
    app.include_router(staff_router, prefix="/api")
    return app


@pytest.fixture
def stub_service():
    service = MagicMock()
    service.enroll.return_value = (
        _StubStaffUser("new-staff-uid", "RM"),
        "https://fake-staff.invalid/invite?email=new@example.com",
    )
    service.update.return_value = _StubStaffUser("target-uid", "RM")
    return service


@pytest.fixture
def client(stub_service) -> Iterator[tuple]:
    engine = create_engine(
        "sqlite:///:memory:", connect_args={"check_same_thread": False}, poolclass=StaticPool,
    )
    Base.metadata.create_all(engine)
    Session = sessionmaker(bind=engine, expire_on_commit=False)

    def _override_get_db():
        db = Session()
        try:
            yield db
        finally:
            db.close()

    stub_user = make_admin_stub(
        Session, role=AdminRole.ADMIN, firebase_uid="uid-staff-router-caller",
        email="caller@example.com",
    )

    app = _make_scratch_app()
    app.dependency_overrides[get_db] = _override_get_db
    app.dependency_overrides[get_current_admin_user] = lambda: stub_user
    app.dependency_overrides[_get_service] = lambda: stub_service
    app.dependency_overrides[get_identity_service] = lambda: MagicMock()
    app.dependency_overrides[get_settings] = lambda: Settings()
    try:
        yield TestClient(app), Session, stub_user
    finally:
        app.dependency_overrides.clear()


def _set_caller_role(Session, stub_user, role: AdminRole) -> None:
    db = Session()
    db.query(AdminProfile).filter_by(user_id=stub_user.id).update({"role": role})
    db.commit()
    db.close()
    # BE-2: stub_user.admin_profile is now loaded eagerly (make_admin_stub) rather
    # than lazy-loaded per access -- keep the cached relationship in sync with the
    # DB row this function just changed, so the very next request sees the new role.
    stub_user.admin_profile.role = role


# --- Positive: super-admin caller ---------------------------------------------------


def test_enroll_super_admin_caller_201(client, stub_service):
    http, _Session, _stub_user = client
    resp = http.post(
        "/api/admin/staff",
        json={"email": "new@example.com", "name": "New Staff", "role": "RM"},
    )
    assert resp.status_code == 201, resp.text
    stub_service.enroll.assert_called_once()


def test_update_super_admin_caller_200(client, stub_service):
    http, _Session, _stub_user = client
    resp = http.patch("/api/admin/staff/target-uid", json={"name": "Renamed"})
    assert resp.status_code == 200, resp.text
    stub_service.update.assert_called_once()


# --- Negative: non-super-admin caller (lacks USER_MANAGE) ---------------------------


@pytest.mark.parametrize("role", [AdminRole.RM, AdminRole.MOBO, AdminRole.PM, AdminRole.PC, AdminRole.COMPLIANCE])
def test_enroll_non_super_admin_caller_403(client, role):
    http, Session, stub_user = client
    _set_caller_role(Session, stub_user, role)

    resp = http.post(
        "/api/admin/staff",
        json={"email": "new@example.com", "name": "New Staff", "role": "RM"},
    )
    assert resp.status_code == 403


@pytest.mark.parametrize("role", [AdminRole.RM, AdminRole.MOBO, AdminRole.PM, AdminRole.PC, AdminRole.COMPLIANCE])
def test_update_non_super_admin_caller_403(client, role):
    http, Session, stub_user = client
    _set_caller_role(Session, stub_user, role)

    resp = http.patch("/api/admin/staff/target-uid", json={"name": "Renamed"})
    assert resp.status_code == 403


